const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const cards=[...document.querySelectorAll('.project')];cards.forEach((c,i)=>c.id=`project-${i+1}`);
const links=[...nav.querySelectorAll('a')];
const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)links.forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})})},{rootMargin:'-20% 0px -55% 0px',threshold:0});document.querySelectorAll('main section[id]').forEach(s=>sectionObserver.observe(s));
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let paused=motionQuery.matches;const motionButton=document.querySelector('.motion-control');
function setMotion(value){paused=value;document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.innerHTML=paused?'Play animation <span aria-hidden="true">▷</span>':'Pause animation <span aria-hidden="true">Ⅱ</span>';document.querySelectorAll('.hero-network').forEach(svg=>{if(paused)svg.pauseAnimations();else svg.unpauseAnimations()})}
motionButton.addEventListener('click',()=>setMotion(!paused));motionQuery.addEventListener('change',e=>setMotion(e.matches));setMotion(paused);
if(!motionQuery.matches){const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('is-visible',entry.isIntersecting)),{threshold:.08});const revealLeft='.director-portrait,.director-quote,.manifesto-cards .pillars article:nth-child(odd),.roadmap .project:nth-child(odd),.footer-about,.contact-intro';const revealRight='.director-copy,.manifesto-cards .pillars article:nth-child(even),.roadmap .project:nth-child(even),.tech-grid article:nth-child(even),.footer-contact,.enquiry,.related-portals,.footer-bottom';document.querySelectorAll('.hero-content,.hero-bottom,.director-portrait,.director-copy,.director-quote,.section-heading,.pillars article,.manifesto-sweep,.project,.tech-grid article,.contact>div,.footer-grid>div,.related-portals,.footer-bottom').forEach((el,i)=>{el.style.setProperty('--reveal-delay',`${(i%4)*80}ms`);el.classList.add('reveal-ready');if(el.matches(revealLeft))el.classList.add('reveal-from-left');else if(el.matches(revealRight))el.classList.add('reveal-from-right');revealObserver.observe(el)})}
document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const body=`${data.get('message')}\n\nRegards,\n${data.get('name')}\n${data.get('email')}`;const url=`mailto:dirit@pakrail.gov.pk?subject=${encodeURIComponent('Website enquiry — Directorate of IT')}&body=${encodeURIComponent(body)}`;window.location.href=url;document.querySelector('#message-status').textContent='Your email app will open with your message. Review it and press Send there. If it does not open, email dirit@pakrail.gov.pk directly.'});
